def transform(grid):
    h, w = len(grid), len(grid[0])
    # A horizontal-band input with a blank first band extends the final band.
    if all(v == 0 for v in grid[0]) and all(len(set(row)) == 1 for row in grid[1:]):
        out = [row[:] for row in grid]
        out[0] = out[-1][:]
        return out

    # Identify the color carried by each down-right diagonal (constant c-r).
    diagonals = {}
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value:
                d = c - r
                diagonals.setdefault(d, set()).add(value)
    colors = {d: next(iter(vals)) for d, vals in diagonals.items() if len(vals) == 1}
    # Find the shortest repeating diagonal-color period compatible with all clues.
    period = 1
    for p in range(1, h + w + 1):
        residues = {}
        ok = True
        for d, color in colors.items():
            k = d % p
            if k in residues and residues[k] != color:
                ok = False
                break
            residues[k] = color
        if ok:
            period, mapping = p, residues
            break
    return [[mapping[(c-r) % period] for c in range(w)] for r in range(h)]
